// hub: subscribers map[int]chan T guarded by a sync.RWMutex
func (h *Hub[T]) Publish(v T) {
	h.mu.RLock()
	defer h.mu.RUnlock()
	for _, ch := range h.subs {
		select {
		case ch <- v: // delivered to every subscriber that keeps up
		default:      // slow subscriber: drop; omit default to block instead
		}
	}
}
